// ── Telegram management bot — authorize, parse & plan ──────────────────────
// MIRRORS scripts/lib/bot-lib.sh (the canonical logic, covered by tests/bot/).
// NO AI and NO network: every command is deterministic. If you change a table
// here, change it in scripts/lib/bot-lib.sh too.
//
// WHITELIST: command -> bot-exec ACTION ('' = answered here, never sent to host).
const CMD_ACTION = {
  status: 'status', health: 'health', check: 'check', projects: 'projects',
  up: 'up', down: 'down', project_up: 'project_up', project_down: 'project_down',
  audit_url: 'audit_url', panel_audit_url: 'panel_audit_url',
  help: '',
};
// Argument rule per action: none | profile (optional, default core) | project | url.
const ARG_RULE = {
  status: 'none', health: 'none', check: 'none', projects: 'none',
  up: 'profile', down: 'profile', project_up: 'project', project_down: 'project',
  audit_url: 'url', panel_audit_url: 'url',
};
const PROFILES = ['core', 'dev', 'auth', 'automation'];
const DEFAULT_PROFILE = 'core';
const PROJECT_RE = /^[a-z][a-z0-9-]{0,38}[a-z0-9]$/;
// URL shape: http(s), no whitespace. The host bridge re-validates AND runs the
// SSRF guard (services/seo/engine/ssrf-check.js) before any audit container.
const URL_RE = /^https?:\/\/[^\s]+$/;

const HELP = [
  'pi-system bot — commands (operator only)', '',
  'Read-only:',
  '  /status      whole-system snapshot',
  '  /health      host hardware health',
  '  /check       read-only readiness gates',
  '  /projects    list generated projects + state', '',
  'State-changing (logged):',
  '  /up <profile>    core | dev | auth | automation (default core)',
  '  /down <profile>  default core',
  '  /project_up <name>    start a generated project',
  '  /project_down <name>  stop a generated project',
  '  /audit_url <url>      audit a single http(s) URL (SSRF-guarded; standard depth)',
  '  /panel_audit_url <url>  same, deep depth (specialist panel — up to ~7 AI calls)', '',
  '  /help        this message',
].join('\n');

// --- the incoming Telegram message ---
const msg = $json.message || $json.channel_post || {};
const senderId = (msg.from && msg.from.id != null) ? String(msg.from.id) : '';
const chatId = (msg.chat && msg.chat.id != null) ? String(msg.chat.id) : senderId;
const text = String(msg.text || msg.caption || '').trim();

// --- ALLOWLIST authorization (FAIL CLOSED) ---
// Empty sender id OR an empty allowlist => deny. Only an exact id match passes.
const allowed = String($env.TELEGRAM_ALLOWED_IDS || '').split(/[\s,;]+/).filter(Boolean);
const authorized = senderId !== '' && allowed.length > 0 && allowed.includes(senderId);

const out = { chatId, senderId, authorized, needsExec: false, action: '', arg: '', label: '', reply: '' };

if (!authorized) {
  console.log('[telegram-bot] DENIED sender=' + (senderId || '?'));
  out.reply = '⛔ Not authorized. This bot is locked to its operator.';
  return [{ json: out }];
}

// --- parse: strip a leading slash, take the first two tokens, drop @botname ---
const parts = text.replace(/^\//, '').split(/\s+/);
const cmd = String(parts[0] || '').replace(/@.*$/, '').toLowerCase();
const arg = parts[1] || '';

if (cmd === '' || cmd === 'help') { out.reply = HELP; return [{ json: out }]; }
if (!(cmd in CMD_ACTION)) { out.reply = '❓ Unknown command: /' + cmd + '\n\n' + HELP; return [{ json: out }]; }

const action = CMD_ACTION[cmd];
const rule = ARG_RULE[action];
let finalArg = arg;

if (rule === 'none' && arg) { out.reply = 'ℹ️ /' + cmd + ' takes no argument.'; return [{ json: out }]; }
if (rule === 'profile') {
  finalArg = arg || DEFAULT_PROFILE;
  if (!PROFILES.includes(finalArg)) {
    out.reply = '⚠️ Invalid profile: ' + finalArg + ' (allowed: core dev auth automation)';
    return [{ json: out }];
  }
}
if (rule === 'project') {
  if (!arg) { out.reply = '⚠️ /' + cmd + ' requires a project name.'; return [{ json: out }]; }
  if (!PROJECT_RE.test(arg)) { out.reply = '⚠️ Malformed project name: ' + arg; return [{ json: out }]; }
  // Existence is re-checked on the host by bot-exec.sh (authoritative).
}
if (rule === 'url') {
  if (!arg) { out.reply = '⚠️ /' + cmd + ' requires a URL.'; return [{ json: out }]; }
  if (!URL_RE.test(arg)) { out.reply = '⚠️ URL must be http(s) and contain no whitespace.'; return [{ json: out }]; }
  // The host re-validates AND runs the SSRF guard before any audit container.
}

out.needsExec = true;
out.action = action;
out.arg = (rule === 'none') ? '' : finalArg;
out.label = '/' + cmd + (out.arg ? ' ' + out.arg : '');
console.log('[telegram-bot] OK sender=' + senderId + ' -> ' + out.label);
return [{ json: out }];
